before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
int main() {
    std::vector<int> values{1, 2, 3};
    std::vector<int> doubled(values.size());
    std::transform(values.begin(), values.end(), doubled.begin(), [](int x) { return x * 2; });
    std::cout << std::accumulate(doubled.begin(), doubled.end(), 0) << '\n';
}

```

